`,l.jsx(t.p,{children:"Some quick statistics:"}),`
`,l.jsxs(t.ul,{children:[`
`,l.jsx(t.li,{children:"45 puzzles, plus 5 post-hunt puzzles"}),`
`,l.jsx(t.li,{children:"3,208 registered participants"}),`
`,l.jsx(t.li,{children:"6,747 hints answered"}),`
`,l.jsx(t.li,{children:"11,412 puzzles solved"}),`
